 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.pop()
                cells.append((rr, cc, grid[rr][cc]))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] != bg:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            comps.append(cells)
    motif = max(comps, key=len)
    r0, r1 = min(r for r,c,v in motif), max(r for r,c,v in motif)
    c0, c1 = min(c for r,c,v in motif), max(c for r,c,v in motif)
    cr, cc = (r0+r1)//2, (c0+c1)//2
    pattern = [(r-cr, c-cc, v) for r,c,v in motif]
    motifset = {(r,c) for r,c,v in motif}
    markers = [(r,c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r,c) not in motifset]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, v in pattern:
            rr, c = mr+dr, mc+dc
            if 0 <= rr < h and 0 <= c < w:
                out[rr][c] = v
    return out
